      },
      "inputs": {
        "script": "const email = $vars['emailReceived1.output'];
const subject = (email && email.subject) ? email.subject.toLowerCase() : '';
const body = (email && email.body && email.body.content) ? email.body.content.toLowerCase() : '';
const importance = (email && email.importance) ? email.importance.toLowerCase() : 'normal';
const urgentKeywords = ['urgent', 'critical', 'asap', 'emergency', 'broken', 'outage', 'down', 'not working', 'issue', 'problem', 'escalate', 'refund', 'billing error', 'account suspended'];
const subjectMatch = urgentKeywords.some(k => subject.includes(k));
const bodyMatch = urgentKeywords.some(k => body.includes(k));
const importanceHigh = importance === 'high';
const isUrgent = subjectMatch || bodyMatch || importanceHigh;
return {
