parameters.new_string:
    {
      "id": "classifyEmail1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Classify Email"
      },
      "inputs": {
        "script": "const email = $vars['emailReceived1.output'];
const subject = (email && email.subject) ? email.subject.toLowerCase() : '';
const body = (email && email.body && email.body.content) ? email.body.content.toLowerCase() : '';
const importance = (email && email.importance) ? email.importance.toLowerCase() : 'normal';
const senderAddr = (email && email.from && email.from.emailAddress && email.from.emailAddress.address) ? email.from.emailAddress.address : '';
const atIdx = senderAddr.indexOf('@');
const senderDomain = atIdx >= 0 ? senderAddr.slice(atIdx + 1).toLowerCase() : '';

// === EDIT THESE LISTS TO MATCH YOUR BUSINESS ===
// VIP domains: emails from these domains get personal attention even without urgency keywords
const vipDomains = ['enterprise.com', 'bigclient.io', 'premiumcorp.net'];
// Urgency keywords: any of these in subject or body triggers P1 escalation
const urgentKeywords = ['urgent', 'critical', 'asap', 'emergency', 'broken', 'outage', 'down', 'not working', 'issue', 'problem', 'escalate', 'refund', 'billing error', 'account suspended', 'legal', 'lawsuit'];
// ================================================

const subjectMatch = urgentKeywords.some(function(k) { return subject.indexOf(k) >= 0; });
const bodyMatch = urgentKeywords.some(function(k) { return body.indexOf(k) >= 0; });
const importanceHigh = importance === 'high';
const isVip = vipDomains.some(function(d) { return senderDomain === d || senderDomain.slice(-(d.length + 1)) === ('.' + d); });

var priority;
if (subjectMatch || bodyMatch || importanceHigh) {
  priority = 'p1';
} else if (isVip) {
  priority = 'p2';
} else {
  priority = 'p3';
}

return {
  priority: priority,
  isVip: isVip,
  reason: priority === 'p1' ? (importanceHigh ? 'High importance flag' : 'Urgent keyword in email') : priority === 'p2' ? 'VIP customer domain' : 'Standard inquiry',
  senderDomain: senderDomain,
  senderEmail: senderAddr,
  subject: (email && email.subject) ? email.subject : '(no subject)',
  emailId: email ? email.id : null
};"
      }
    },

